class Handler {
    var stored: (() -> Int)?
    func setup() {
        var multiplier = 3
        stored = { [multiplier] in
            return multiplier * 4
        }
        multiplier = 10
    }
}
let handler = Handler()
handler.setup()
print(handler.stored?() ?? 0)

class Person {
    var name = "Alex"
}
var person: Person? = Person()
let closure = { [weak person] in
    print(person?.name ?? "None")
}
person = nil
closure()

func executeTwice(action: () -> Void) {
    action()
    action()
}
var counter = 0
executeTwice {
    counter += 1
}
print(counter)

class Worker {
    var job: (() -> String)?
    func register(work: @escaping () -> String) {
        job = work
    }
}
let worker = Worker()
let greeting = "Hello"
worker.register {
    return "\(greeting) World"
}
print(worker.job?() ?? "Empty")

class DataStore {
    var value = 100
    func makeGetter() -> () -> Int {
        return { [weak self] in
            return self?.value ?? -1
        }
    }
}
var store: DataStore? = DataStore()
let getter = store!.makeGetter()
print(getter())

