class AsyncFetcher {
    var completion: (() -> Void)?
    func fetch(callback: @escaping () -> Void) {
        completion = callback
    }
}
let fetcher = AsyncFetcher()
fetcher.fetch {
    print("Fetched data")
}
fetcher.completion?()

class ViewModel {
    var count = 10
    func makeHandler() -> () -> Int {
        return { [weak self] in
            return self?.count ?? 0
        }
    }
}
let vm = ViewModel()
let actionHandler = vm.makeHandler()
print(actionHandler())

func applyOperation(value: Int, operation: (Int) -> Int) -> Int {
    return operation(value)
}
let result = applyOperation(value: 7) { $0 * 3 }
print(result)
